<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { DataBaseIcon, LinkIcon, RefreshIcon, SearchIcon } from 'tdesign-icons-vue-next'
import { api } from '../api'
import { hasRole } from '../auth'

interface DataSource { id:string; name:string; type:string; status:string; access:string; objects:number; connection?:Record<string,any>; onboarding?:Record<string,any>; last_scan_at?:string }
const emptyForm=()=>({name:'',type:'postgresql',host:'',port:5432,database:'',username:'',password:'',schema_name:'',catalog:'',compatibility_mode:'',service_kind:'service',jdbc_url:'',driver_id:'',product_override:''})
const sources=ref<DataSource[]>([]),products=ref<any[]>([]),drivers=ref<any[]>([])
const selectedId=ref(''),sourceSearch=ref(''),creating=ref(false),newMode=ref(false),hydrating=ref(false)
const form=ref(emptyForm()),advancedProperties=ref('{}'),passwordConfigured=ref(false),testReceipt=ref('')
const connectionState=ref<'idle'|'testing'|'success'|'error'>('idle'),connectionMessage=ref(''),detectedVersion=ref(''),detectedProduct=ref(''),pageError=ref('')
const canManage=computed(()=>hasRole('data_steward','admin'));let poller:ReturnType<typeof setInterval>|undefined
const selected=computed(()=>sources.value.find(item=>item.id===selectedId.value)||null)
const filteredSources=computed(()=>{const q=sourceSearch.value.trim().toLowerCase();return q?sources.value.filter(item=>`${item.name} ${item.type}`.toLowerCase().includes(q)):sources.value})
const activeOnboarding=computed(()=>selected.value?.onboarding||null)
const terminalStatuses=new Set(['completed','completed_with_pending','failed','cancelled'])
function isModelingActive(job?:Record<string,any>|null){return !!job&&!terminalStatuses.has(job.status)}
const modelingBusy=computed(()=>isModelingActive(activeOnboarding.value))
const modelingAction=ref('')
const canCancelModeling=computed(()=>modelingBusy.value&&activeOnboarding.value?.phase!=='publishing'&&activeOnboarding.value?.status!=='cancelling')
const connectionSignature=computed(()=>JSON.stringify({type:form.value.type,host:form.value.host,port:form.value.port,database:form.value.database,username:form.value.username,password:form.value.password,schema_name:form.value.schema_name,catalog:form.value.catalog,compatibility_mode:form.value.compatibility_mode,service_kind:form.value.service_kind,jdbc_url:form.value.jdbc_url,driver_id:form.value.driver_id,product_override:form.value.product_override,properties:advancedProperties.value}))
watch(connectionSignature,()=>{if(newMode.value&&!hydrating.value){testReceipt.value='';connectionState.value='idle';connectionMessage.value='';detectedVersion.value='';detectedProduct.value=''}})
function connectionBody(){return{name:form.value.name,type:form.value.type,test_receipt:testReceipt.value||null,connection:{...Object.fromEntries(Object.entries(form.value).filter(([key])=>key!=='name')),port:Number(form.value.port),properties:JSON.parse(advancedProperties.value||'{}'),config_version:2}}}
function phaseLabel(phase?:string){return({queued:'等待开始',testing:'验证连接',probing:'探测数据库能力',scanning:'扫描表结构',discovering:'发现关联关系',profiling:'核验关系证据',understanding_tables:'理解表与字段职责',researching:'验证关系依据',reading:'提取搜索线索',extracting_keywords:'提取全库关键词',organizing_recall_groups:'整理关键词召回组',organization_complete:'召回组整理完成',analyzing_large_groups:'自主分析大命中组',keywords_complete:'关键词提取完成',retrieval_complete:'关键词检索完成',discovery_complete:'关系发现完成',interrupted:'阶段任务已中断',comparing:'分批分析关联',expanding:'补充搜索线索',checking_references:'核查引用完整性',auditing_evidence:'复核新增证据',auditing_domains:'核查编号体系',cancelled:'已取消',cancelling:'正在取消',publishing:'正在发布关系',building:'生成单源本体',using_persisted_metadata:'读取已保存结构',complete:'关联关系已更新',metadata_complete:'结构获取完成，请手动更新关联关系',failed:'处理失败',resuming:'恢复任务'} as Record<string,string>)[phase||'']||phase||'尚未开始'}
function statusLabel(status:string){return({healthy:'连接正常',unsafe:'账号权限过高',unverified:'等待验证',scan_only:'仅支持扫描'} as Record<string,string>)[status]||status}
function statusTheme(status:string){return status==='healthy'?'success':status==='unsafe'?'danger':'warning'}
async function loadSources(first=false){const items=(await api.get('/datasources')).data as DataSource[];await Promise.all(items.map(async item=>{try{item.onboarding=(await api.get(`/datasources/${item.id}/onboarding`)).data}catch(cause:any){if(cause.response?.status!==404)throw cause}}));sources.value=items;if(first&&!selectedId.value&&items.length)await selectSource(items[0])}
async function selectSource(item:DataSource){pageError.value='';newMode.value=false;selectedId.value=item.id;hydrating.value=true;try{const connection=(await api.get(`/datasources/${item.id}/connection`)).data;passwordConfigured.value=!!connection.password_configured;form.value={...emptyForm(),...connection,name:item.name,type:item.type,password:''};advancedProperties.value=JSON.stringify(connection.properties||{},null,2);detectedVersion.value=item.connection?.version||'';detectedProduct.value=item.connection?.product||'';connectionState.value=item.status==='healthy'?'success':'idle';connectionMessage.value=item.status==='healthy'?'已通过连接验证':''}catch(cause:any){pageError.value=cause.response?.data?.detail||'无法读取数据源连接配置'}finally{hydrating.value=false}}
function startCreate(){selectedId.value='';newMode.value=true;hydrating.value=true;form.value=emptyForm();advancedProperties.value='{}';passwordConfigured.value=false;testReceipt.value='';connectionState.value='idle';connectionMessage.value='';detectedVersion.value='';detectedProduct.value='';hydrating.value=false}
function selectProduct(){const product=products.value.find(item=>item.id===form.value.type);form.value.port=product?.port||5432;form.value.driver_id=product?.driver_id||'';form.value.compatibility_mode=form.value.type==='oceanbase'?'mysql':''}
async function testConnection(){connectionState.value='testing';connectionMessage.value='';pageError.value='';try{if(newMode.value){const result=(await api.post('/datasource-connection-test',connectionBody())).data;testReceipt.value=result.test_receipt;detectedVersion.value=result.version||'';detectedProduct.value=result.product||result.database||'';connectionMessage.value=`连接成功${result.database?` · ${result.database}`:''}${result.version?` · ${result.version}`:''}`}else if(selected.value){const result=(await api.post(`/datasources/${selected.value.id}/test`)).data;detectedVersion.value=result.version||detectedVersion.value;detectedProduct.value=result.product||detectedProduct.value;connectionMessage.value=`连接成功${result.version?` · ${result.version}`:''}`;await loadSources()}connectionState.value='success'}catch(cause:any){testReceipt.value='';connectionState.value='error';connectionMessage.value=cause.response?.data?.detail||cause.message||'连接失败'}}
async function saveSource(){creating.value=true;pageError.value='';try{if(newMode.value){if(!testReceipt.value)return;const created=(await api.post('/datasources',connectionBody())).data;await loadSources();const item=sources.value.find(source=>source.id===created.id);if(item)await selectSource(item)}else if(selected.value){await api.patch(`/datasources/${selected.value.id}`,{name:form.value.name});await loadSources()}}catch(cause:any){pageError.value=cause.response?.data?.detail||cause.message||'保存失败'}finally{creating.value=false}}
async function modelingOperation(action:'scan'|'analyze'|'cancel'|'resume'){
  const item=selected.value;if(!item||modelingAction.value)return
  const job=item.onboarding
  modelingAction.value=action;pageError.value=''
  try{
    const path=action==='resume'?`/datasources/${item.id}/onboarding/${job?.id}/resume`:action==='cancel'?`/datasources/${item.id}/onboarding/${job?.id}/cancel`:action==='analyze'?`/datasources/${item.id}/relationships/analyze`:`/datasources/${item.id}/rescan`
    item.onboarding=(await api.post(path)).data
    await loadSources()
  }catch(cause:any){pageError.value=cause.response?.data?.detail||'任务操作失败，请重试'}finally{modelingAction.value=''}
}
async function resumeAnalysis(){await modelingOperation('resume')}
async function rescan(){await modelingOperation('scan')}
async function analyzeRelations(){await modelingOperation('analyze')}
async function cancelModeling(){await modelingOperation('cancel')}

const showTables=ref(false),tableQuery=ref(''),tablePage=ref(1),tablePageSize=ref(20),tableTotal=ref(0),tableItems=ref<any[]>([]),tableDetail=ref<any>(null),drawerLoading=ref(false)
async function loadTables(reset=false){if(!selected.value)return;if(reset)tablePage.value=1;drawerLoading.value=true;tableDetail.value=null;try{const result=(await api.get(`/datasources/${selected.value.id}/tables`,{params:{page:tablePage.value,page_size:tablePageSize.value,query:tableQuery.value}})).data;tableItems.value=result.items;tableTotal.value=result.total}finally{drawerLoading.value=false}}
async function openTables(){showTables.value=true;tableQuery.value='';await loadTables(true)}
async function openTableDetail(table:any){if(!selected.value)return;drawerLoading.value=true;try{tableDetail.value=(await api.get(`/datasources/${selected.value.id}/tables/detail`,{params:{table_id:table.id}})).data}finally{drawerLoading.value=false}}
function changeTablePage(value:number){tablePage.value=value;void loadTables()}
function changeTablePageSize(value:number){tablePageSize.value=value;void loadTables(true)}

const showRelations=ref(false),relationItems=ref<any[]>([]),relationPage=ref(1),relationTotal=ref(0),relationEditing=ref(false),relationBusy=ref(false),relationError=ref('')
const relationForm=ref<any>({}),relationTables=ref<any[]>([]),relationColumns=ref<Record<string,any[]>>({source:[],target:[]})
async function loadRelations(){if(!selected.value)return;const r=(await api.get(`/datasources/${selected.value.id}/relationships`,{params:{page:relationPage.value,page_size:20}})).data;relationItems.value=r.items;relationTotal.value=r.total}
async function searchRelationTables(query=''){if(!selected.value)return;const r=(await api.get(`/datasources/${selected.value.id}/tables`,{params:{query,page:1,page_size:100}})).data;relationTables.value=r.items.map((t:any)=>({label:t.id,value:t.id}))}
async function openRelations(){showRelations.value=true;relationEditing.value=false;relationPage.value=1;relationError.value='';try{await loadRelations()}catch(e:any){relationError.value=e.response?.data?.detail||'无法读取关联关系'}}
async function relationSide(side:'source'|'target'){const id=relationForm.value[side+'_table_id'];relationColumns.value[side]=id?(await api.get(`/datasources/${selected.value?.id}/tables/detail`,{params:{table_id:id}})).data.columns:[]}
async function editSourceRelation(r?:any){relationError.value='';relationForm.value=r?JSON.parse(JSON.stringify(r)):{source_table_id:'',target_table_id:'',cardinality:'N:1',key_pairs:[{source:'',target:''}]};relationEditing.value=true;try{await searchRelationTables();for(const id of [r?.source_table_id,r?.target_table_id].filter(Boolean)){if(!relationTables.value.some(t=>t.value===id))relationTables.value.push({label:id,value:id})}await Promise.all([relationSide('source'),relationSide('target')])}catch(e:any){relationError.value=e.response?.data?.detail||'无法读取表字段'}}
async function saveSourceRelation(){if(!selected.value)return;relationBusy.value=true;relationError.value='';try{const f=relationForm.value;const body={source_table_id:f.source_table_id,target_table_id:f.target_table_id,key_pairs:f.key_pairs,cardinality:f.cardinality};if(f.id)await api.put(`/datasources/${selected.value.id}/relationships/${f.id}`,body);else await api.post(`/datasources/${selected.value.id}/relationships`,body);relationEditing.value=false;await loadRelations()}catch(e:any){relationError.value=e.response?.data?.detail||'保存关系失败'}finally{relationBusy.value=false}}
const deletingSourceRelation=ref<any>(null)
async function deleteSourceRelation(){if(!selected.value||!deletingSourceRelation.value)return;relationBusy.value=true;relationError.value='';try{await api.delete(`/datasources/${selected.value.id}/relationships/${deletingSourceRelation.value.id}`);deletingSourceRelation.value=null;relationPage.value=1;await loadRelations()}catch(e:any){relationError.value=e.response?.data?.detail||'删除关系失败'}finally{relationBusy.value=false}}

const showDrivers=ref(false),editingDriverId=ref(''),driverFiles=ref<File[]>([]),driverConfig=ref(JSON.stringify({name:'',driver_class:'',version:'',enabled:false,dialect:'',readonly_strategy:'',pagination:'baseline',type_mapping:{},metadata_queries:{}},null,2))
const driverKeys=['name','driver_class','version','enabled','dialect','readonly_strategy','pagination','type_mapping','metadata_queries']
async function installDriver(){try{const value=JSON.parse(driverConfig.value);if(editingDriverId.value)await api.put(`/settings/database-drivers/${editingDriverId.value}`,value);else{const data=new FormData();data.append('config',driverConfig.value);driverFiles.value.forEach(file=>data.append('files',file));await api.post('/settings/database-drivers',data,{timeout:200000})}drivers.value=(await api.get('/settings/database-drivers')).data;editingDriverId.value=''}catch(cause:any){pageError.value=cause.response?.data?.detail||'驱动保存失败'}}
function editDriver(driver:any){editingDriverId.value=driver.id;driverConfig.value=JSON.stringify(Object.fromEntries(driverKeys.filter(key=>key in driver).map(key=>[key,driver[key]])),null,2)}
async function toggleDriver(driver:any){const value=Object.fromEntries(driverKeys.filter(key=>key in driver).map(key=>[key,driver[key]]));value.enabled=!driver.enabled;await api.put(`/settings/database-drivers/${driver.id}`,value);drivers.value=(await api.get('/settings/database-drivers')).data}
onMounted(async()=>{try{products.value=(await api.get('/datasource-products')).data;drivers.value=(await api.get('/settings/database-drivers')).data;await loadSources(true);poller=setInterval(()=>{void loadSources()},3000)}catch(cause:any){pageError.value=cause.response?.data?.detail||'无法加载数据源'}})
onUnmounted(()=>{if(poller)clearInterval(poller)})
</script>

<template>
  <div class="page datasource-page">
    <div class="page-header"><div><h1>数据源</h1><p>维护只读数据库连接，查看已扫描的表结构与关联关系。</p></div><div class="header-actions"><t-button v-if="hasRole('admin')" variant="outline" @click="showDrivers=true">驱动管理</t-button><t-button v-if="canManage" theme="primary" @click="startCreate">添加数据源</t-button></div></div>
    <t-alert v-if="pageError" theme="error" :message="pageError" closable @close="pageError=''" />
    <div class="workspace">
      <aside class="source-sidebar"><div class="source-search"><t-input v-model="sourceSearch" clearable placeholder="搜索数据源"><template #prefix-icon><SearchIcon /></template></t-input></div><button v-for="item in filteredSources" :key="item.id" class="source-item" :class="{active:item.id===selectedId}" @click="selectSource(item)"><span class="source-icon"><DataBaseIcon /></span><span class="source-copy"><strong>{{ item.name }}</strong><small>{{ item.type }} · {{ item.objects }} 张表</small><small v-if="item.onboarding&&isModelingActive(item.onboarding)">{{ phaseLabel(item.onboarding.phase) }} {{ item.onboarding.progress }}%</small></span><i class="connection-dot" :class="item.status"></i></button><div v-if="!filteredSources.length" class="empty-list">暂无数据源</div></aside>
      <main class="source-form-panel">
        <div class="form-heading"><div><span class="eyebrow">{{ newMode?'NEW DATA SOURCE':'DATA SOURCE' }}</span><h2>{{ newMode?'创建数据源':selected?.name||'请选择数据源' }}</h2></div><t-tag v-if="selected" :theme="statusTheme(selected.status) as any" variant="light">{{ statusLabel(selected.status) }}</t-tag></div>
        <template v-if="newMode||selected">
          <section v-if="selected&&activeOnboarding" class="modeling-status"><div><strong>{{ phaseLabel(activeOnboarding.phase) }}</strong><span>{{ activeOnboarding.progress||0 }}%</span></div><t-progress :percentage="activeOnboarding.progress||0" :label="false" size="small" /><small v-if="modelingBusy">{{ activeOnboarding.status==='cancelling'?'正在停止任务，请稍候。':activeOnboarding.phase==='publishing'?'正在发布完整结果，请稍候。':'后台处理中，已扫描的数据表仍可正常查看。' }}</small><small v-else-if="activeOnboarding.status==='cancelled'">任务已取消，可以重新分析关系。已有生效关系保持可用。</small><t-button v-if="canManage&&modelingBusy" size="small" theme="danger" variant="outline" :loading="modelingAction==='cancel'||activeOnboarding.status==='cancelling'" :disabled="!canCancelModeling||!!modelingAction" @click="cancelModeling">取消任务</t-button><small v-if="activeOnboarding.error" class="error-text">{{ activeOnboarding.error }}</small></section>
          <section class="form-section"><div class="section-title"><h3>连接信息</h3><p>{{ newMode?'填写后先测试连接，通过后方可创建。':'连接参数创建后锁定；如需更换连接，请新建数据源。' }}</p></div><div class="form-grid">
            <label class="span-2">数据源名称<t-input v-model="form.name" :disabled="!canManage" /></label><label>数据库类型<t-select v-model="form.type" :disabled="!newMode" @change="selectProduct"><t-option v-for="product in products" :key="product.id" :value="product.id" :label="product.label" /></t-select></label><label>数据库版本<t-input :value="[detectedProduct,detectedVersion].filter(Boolean).join(' ')||'连接测试后自动识别'" disabled /></label><label>数据库地址<t-input v-model="form.host" :disabled="!newMode" /></label><label>端口<t-input-number v-model="form.port" :min="1" :max="65535" :disabled="!newMode" /></label><label>数据库名<t-input v-model="form.database" :disabled="!newMode" /></label><label>用户名<t-input v-model="form.username" :disabled="!newMode" autocomplete="off" /></label><label class="span-2">密码<t-input v-model="form.password" type="password" :disabled="!newMode" autocomplete="new-password" :placeholder="newMode?'填写只读账号密码':passwordConfigured?'已安全配置':'未配置'" /></label>
          </div><details class="advanced"><summary>高级连接配置</summary><div class="form-grid advanced-grid"><label>Schema<t-input v-model="form.schema_name" :disabled="!newMode" /></label><label>Catalog<t-input v-model="form.catalog" :disabled="!newMode" /></label><label v-if="!['mysql','postgresql'].includes(form.type)">JDBC 驱动<t-select v-model="form.driver_id" :disabled="!newMode"><t-option v-for="driver in drivers.filter(item=>item.enabled)" :key="driver.id" :value="driver.id" :label="`${driver.name} ${driver.version}`" /></t-select></label><label v-if="form.type==='oceanbase'">兼容模式<t-select v-model="form.compatibility_mode" :disabled="!newMode"><t-option value="mysql" label="MySQL" /><t-option value="oracle" label="Oracle" /></t-select></label><label v-if="!['mysql','postgresql'].includes(form.type)" class="span-2">JDBC 连接串<t-input v-model="form.jdbc_url" :disabled="!newMode" /></label><label v-if="newMode" class="span-2">连接属性 JSON<t-textarea v-model="advancedProperties" /></label></div></details></section>
          <div v-if="connectionState!=='idle'" class="connection-result" :class="connectionState"><span class="result-dot"></span><strong>{{ connectionState==='testing'?'正在测试连接':connectionMessage }}</strong></div>
          <section v-if="selected" class="resource-links"><button :disabled="selected.objects<1" @click="openTables"><DataBaseIcon /><span><strong>查看数据表</strong><small>{{ selected.objects }} 张表，查看字段与约束</small></span><b>→</b></button><button :disabled="selected.objects<1" @click="openRelations"><LinkIcon /><span><strong>查看关联关系</strong><small>查看、编辑或删除表间关系</small></span><b>→</b></button></section>
          <div class="form-actions"><t-button variant="outline" :loading="connectionState==='testing'" @click="testConnection"><template #icon><LinkIcon /></template>测试连接</t-button><t-button v-if="selected&&canManage" variant="outline" :loading="modelingAction==='scan'" :disabled="modelingBusy||!!modelingAction" @click="rescan"><template #icon><RefreshIcon /></template>重新扫描</t-button><t-button v-if="selected&&canManage&&activeOnboarding?.status==='failed'&&activeOnboarding?.details?.checkpoint_ref" variant="outline" :loading="modelingAction==='resume'" :disabled="!!modelingAction" @click="resumeAnalysis">继续上次分析</t-button><t-button v-if="selected&&canManage" variant="outline" :loading="modelingAction==='analyze'" :disabled="modelingBusy||!!modelingAction" @click="analyzeRelations"><template #icon><RefreshIcon /></template>更新关联关系</t-button><t-button v-if="canManage" theme="primary" :loading="creating" :disabled="!form.name||(newMode&&connectionState!=='success')" @click="saveSource">{{ newMode?'创建数据源':'保存名称' }}</t-button></div>
        </template><div v-else class="blank-state"><DataBaseIcon size="48px" /><h3>选择一个数据源</h3><p>查看连接信息、表结构和关联关系。</p></div>
      </main>
    </div>

    <t-drawer :visible="showTables" :header="tableDetail?'表结构详情':`${selected?.name||''} · 数据表`" :footer="false" size="min(1040px, 96vw)" @close="showTables=false"><div v-if="!tableDetail" class="drawer-body"><div class="drawer-toolbar"><t-input v-model="tableQuery" clearable placeholder="搜索表名、Schema 或说明" @enter="loadTables(true)"><template #prefix-icon><SearchIcon /></template></t-input><t-button @click="loadTables(true)">搜索</t-button></div><div class="data-table"><div class="table-row table-head"><span>表名</span><span>类型</span><span>说明</span><span>字段数</span><span></span></div><div v-for="table in tableItems" :key="table.id" class="table-row"><span><strong>{{ [table.schema,table.name].filter(Boolean).join('.') }}</strong><small>{{ table.primary_keys?.length?`主键：${table.primary_keys.flatMap((key:any)=>key.columns||[]).join(', ')}`:'未声明主键' }}</small></span><span>{{ table.kind||'TABLE' }}</span><span>{{ table.description||'—' }}</span><span>{{ table.column_count }}</span><span><t-button variant="text" @click="openTableDetail(table)">查看 Schema</t-button></span></div></div><t-pagination :current="tablePage" :page-size="tablePageSize" :total="tableTotal" :page-size-options="[10,20,50,100]" @current-change="changeTablePage" @page-size-change="changeTablePageSize" /></div><div v-else class="schema-detail"><t-button variant="text" @click="tableDetail=null">← 返回表目录</t-button><div class="schema-title"><h3>{{ [tableDetail.schema,tableDetail.name].filter(Boolean).join('.') }}</h3><p>{{ tableDetail.description||'暂无表说明' }}</p></div><div class="column-table"><div class="column-head"><span>字段</span><span>类型</span><span>可空</span><span>说明</span></div><div v-for="column in tableDetail.columns||[]" :key="column.name" class="column-line"><code>{{ column.name }}</code><span>{{ column.raw_type||column.type }}</span><span>{{ column.nullable?'是':'否' }}</span><span>{{ column.description||column.comment||'—' }}</span></div></div><div class="constraint-grid"><article><h4>主键</h4><pre>{{ JSON.stringify(tableDetail.primary_keys||[],null,2) }}</pre></article><article><h4>唯一约束</h4><pre>{{ JSON.stringify(tableDetail.unique_constraints||[],null,2) }}</pre></article><article><h4>外键</h4><pre>{{ JSON.stringify(tableDetail.foreign_keys||[],null,2) }}</pre></article><article><h4>索引</h4><pre>{{ JSON.stringify(tableDetail.indexes||[],null,2) }}</pre></article></div></div></t-drawer>

    <t-drawer v-model:visible="showRelations" :header="`${selected?.name||''} · 关联关系`" :footer="false" size="min(1040px,96vw)">
      <div class="drawer-body"><t-alert v-if="relationError" theme="error" :message="relationError" />
      <template v-if="!relationEditing"><div class="drawer-toolbar"><t-button v-if="canManage" theme="primary" :disabled="modelingBusy" @click="editSourceRelation()">添加关联关系</t-button><t-button v-if="canManage" :disabled="modelingBusy||!!modelingAction" :loading="modelingAction==='analyze'" @click="analyzeRelations">更新关联关系</t-button><t-button v-if="canManage&&canCancelModeling" theme="danger" @click="cancelModeling">取消任务</t-button></div>
      <div class="relation-list"><article v-for="r in relationItems" :key="r.id" class="relation-card"><div class="relation-expression"><span><strong>{{r.source_table_id}}</strong><code>{{r.source_columns.join(', ')}}</code></span><b>{{r.cardinality}}</b><span><strong>{{r.target_table_id}}</strong><code>{{r.target_columns.join(', ')}}</code></span></div><div class="relation-meta"><t-tag theme="success">已生效</t-tag><div v-if="canManage" class="relation-actions"><t-button variant="text" :disabled="modelingBusy" @click="editSourceRelation(r)">编辑</t-button><t-button variant="text" theme="danger" :disabled="modelingBusy" @click="deletingSourceRelation=r">删除</t-button></div></div></article><div v-if="!relationItems.length" class="empty-list">暂无关联关系</div></div><t-pagination v-model="relationPage" :total="relationTotal" :page-size="20" @current-change="loadRelations" /></template>
      <div v-else class="relation-editor"><t-button variant="text" @click="relationEditing=false">返回关系列表</t-button><div class="form-grid"><label>来源表<t-select v-model="relationForm.source_table_id" filterable :options="relationTables" @search="searchRelationTables" @change="relationSide('source')" /></label><label>目标表<t-select v-model="relationForm.target_table_id" filterable :options="relationTables" @search="searchRelationTables" @change="relationSide('target')" /></label><label>关联基数<t-select v-model="relationForm.cardinality" :options="['1:1','1:N','N:1','N:N','unknown'].map(v=>({label:v,value:v}))" /></label></div><h3>关联条件</h3><div v-for="(pair,i) in relationForm.key_pairs" :key="i" class="pair-row"><t-select v-model="pair.source" filterable :options="relationColumns.source.map(c=>({label:c.name,value:c.name}))" /><span>=</span><t-select v-model="pair.target" filterable :options="relationColumns.target.map(c=>({label:c.name,value:c.name}))" /><t-button variant="text" :disabled="relationForm.key_pairs.length===1" @click="relationForm.key_pairs.splice(i,1)">移除</t-button></div><t-button :disabled="relationForm.key_pairs.length>=8" @click="relationForm.key_pairs.push({source:'',target:''})">添加字段对</t-button><div class="form-actions"><t-button :loading="relationBusy" :disabled="!relationForm.source_table_id||!relationForm.target_table_id||relationForm.key_pairs.some((p:any)=>!p.source||!p.target)" theme="primary" @click="saveSourceRelation">保存并同步本体</t-button></div></div></div>
    </t-drawer>
    <t-dialog :visible="!!deletingSourceRelation" header="删除关联关系" :confirm-btn="{content:'确认删除',theme:'danger',loading:relationBusy}" @confirm="deleteSourceRelation" @close="deletingSourceRelation=null">将删除此数据源关系，并同步移除引用它的业务域本体关系。</t-dialog>
    <t-dialog v-model:visible="showDrivers" header="管理员 JDBC 驱动" :footer="false" width="720px"><div class="driver-dialog"><div v-for="driver in drivers" :key="driver.id" class="driver-row"><strong>{{ driver.name }} {{ driver.version }}</strong><span>{{ driver.enabled?'已启用':'未启用' }}</span><t-button v-if="!driver.builtin" size="small" variant="text" @click="editDriver(driver)">编辑</t-button><t-button v-if="!driver.builtin" size="small" variant="text" @click="toggleDriver(driver)">{{ driver.enabled?'停用':'启用' }}</t-button></div><label v-if="!editingDriverId">驱动 JAR<input type="file" accept=".jar" multiple @change="driverFiles=Array.from(($event.target as HTMLInputElement).files||[])" /></label><label>驱动配置 JSON<t-textarea v-model="driverConfig" :autosize="{minRows:8,maxRows:16}" /></label><div class="header-actions"><t-button v-if="editingDriverId" variant="text" @click="editingDriverId=''">取消编辑</t-button><t-button @click="installDriver">{{ editingDriverId?'保存适配':'上传驱动包' }}</t-button></div></div></t-dialog>
  </div>
</template>

